/**
 * Sub-path type declarations for the simple-icons the Integrations gallery draws
 * (app/components/integrations/IntegrationLogo.tsx), beyond the ones declared in
 * react-simple-icons.d.ts - see that file for why each icon is declared by name rather than
 * through the package barrel. Must stay a script file (no top-level imports), and an icon
 * must be declared in only one of the two files.
 */

declare module '@icons-pack/react-simple-icons/icons/SiGithub' {
  import type React from 'react';
  const SiGithub: React.ForwardRefExoticComponent<
    React.SVGProps<SVGSVGElement> & {
      title?: string;
      color?: string;
      size?: string | number;
    } & React.RefAttributes<SVGSVGElement>
  >;
  const defaultColor: string;
  export { SiGithub as default, defaultColor };
}

